use std::path::PathBuf;
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::process::Command;
use std::collections::HashMap;

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut opt = Options::new();

    // Parse arguments
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_help();
                return;
            },
            "--version" | "-V" => {
                println!("i3-style 1.0");
                return;
            },
            "--list-all" | "-l" => {
                opt.list_all = true;
            },
            "--config" | "-c" => {
                if i + 1 < args.len() {
                    opt.config = Some(PathBuf::from(&args[i + 1]));
                    i += 1;
                }
            },
            "--output" | "-o" => {
                if i + 1 < args.len() {
                    opt.output = Some(PathBuf::from(&args[i + 1]));
                    i += 1;
                }
            },
            "--to-theme" | "-t" => {
                if i + 1 < args.len() {
                    opt.to_theme = Some(PathBuf::from(&args[i + 1]));
                    i += 1;
                }
            },
            "--save" | "-s" => {
                opt.save = true;
            },
            "--reload" | "-r" => {
                opt.reload = true;
            },
            _ => {
                if !args[i].starts_with('-') {
                    opt.theme = Some(args[i].clone());
                }
            }
        }
        i += 1;
    }

    if opt.list_all {
        print_available_themes();
        return;
    }

    if let Some(to_theme_path) = opt.to_theme {
        convert_config_to_theme(&to_theme_path, &opt.output);
        return;
    }

    if let Some(theme_name) = opt.theme {
        apply_theme(&theme_name, &opt.config, &opt.output, opt.save, opt.reload);
    } else {
        eprintln!("Could not find i3 config");
    }
}

