struct Options {
    theme: Option<String>,
    config: Option<PathBuf>,
    output: Option<PathBuf>,
    to_theme: Option<PathBuf>,
    save: bool,
    reload: bool,
    list_all: bool,
}

impl Options {
    fn new() -> Self {
        Options {
            theme: None,
            config: None,
            output: None,
            to_theme: None,
            save: false,
            reload: false,
            list_all: false,
        }
    }
}

