use themes::{get_theme, ColorScheme};

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut opt = Options::new();

    // Parse arguments
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_help();
                return;
            },
            "--version" | "-V" => {
                println!("i3-style 1.0");
                return;
            },
            "--list-all" | "-l" => {
                opt.list_all = true;
            },
            "--config" | "-c" => {
                if i + 1 < args.len() {
                    opt.config = Some(PathBuf::from(&args[i + 1]));
                    i += 1;
                }
            },
            "--output" | "-o" => {
                if i + 1 < args.len() {
                    opt.output = Some(PathBuf::from(&args[i + 1]));
                    i += 1;
                }
            },
            "--to-theme" | "-t" => {
                if i + 1 < args.len() {
                    opt.to_theme = Some(PathBuf::from(&args[i + 1]));
                    i += 1;
                }
            },
            "--save" | "-s" => {
                opt.save = true;
            },
            "--reload" | "-r" => {
                opt.reload = true;
            },
            _ => {
                if !args[i].starts_with('-') {
                    opt.theme = Some(args[i].clone());
                }
            }
        }
        i += 1;
    }

    if opt.list_all {
        print_available_themes();
        return;
    }

    if let Some(to_theme_path) = &opt.to_theme {
        if to_theme_path.as_os_str().is_empty() || to_theme_path.to_string_lossy() == "" {
            // No argument provided, return
            return;
        }
        convert_config_to_theme(to_theme_path, &opt.output);
        return;
    }

    if let Some(theme_name) = opt.theme {
        apply_theme(&theme_name, &opt.config, &opt.output, opt.save, opt.reload);
    } else {
        eprintln!("Could not find i3 config");
    }
}

#[derive(Debug)]
struct Options {
    theme: Option<String>,
    config: Option<PathBuf>,
    output: Option<PathBuf>,
    to_theme: Option<PathBuf>,
    save: bool,
    reload: bool,
    list_all: bool,
}

impl Options {
    fn new() -> Self {
        Options {
            theme: None,
            config: None,
            output: None,
            to_theme: None,
            save: false,
            reload: false,
            list_all: false,
        }
    }
}

fn print_help() {
    println!("i3-style 1.0");
    println!("Make your i3 config a bit more stylish");
    println!();
    println!("USAGE:");
    println!("    executable [FLAGS] [OPTIONS] [theme]");
    println!();
    println!("FLAGS:");
    println!("    -h, --help        Prints help information");
    println!("    -l, --list-all    Print a list of all available themes");
    println!("    -r, --reload      Apply the theme by reloading the config");
    println!("    -s, --save        Set the output file to the path of the input file");
    println!("    -V, --version     Prints version information");
    println!();
    println!("OPTIONS:");
    println!("    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.");
    println!("    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>");
    println!("    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others");
    println!("                             [default: ]");
    println!();
    println!("ARGS:");
    println!("    <theme>    The theme to use");
}

