fn apply_theme(theme_name: &str, config_path: &Option<PathBuf>, output_path: &Option<PathBuf>, save: bool, _reload: bool) {
    let theme = match get_theme(theme_name) {
        Some(t) => t,
        None => {
            // Try to load theme from file path
            if let Ok(content) = fs::read_to_string(theme_name) {
                // Parse YAML theme
                match parse_theme_file(&content) {
                    Ok(t) => t,
                    Err(_) => {
                        eprintln!("Unknown theme: {}", theme_name);
                        return;
                    }
                }
            } else {
                eprintln!("Unknown theme: {}", theme_name);
                return;
            }
        }
    };

    // Determine config file location
    let config_file = match config_path {
        Some(p) => p.clone(),
        None => {
            // Default to ~/.config/i3/config
            if let Ok(home) = env::var("HOME") {
                PathBuf::from(format!("{}/.config/i3/config", home))
            } else {
                eprintln!("Could not find i3 config");
                return;
            }
        }
    };

    // Read config file
    let config_content = match fs::read_to_string(&config_file) {
        Ok(c) => c,
        Err(_) => {
            eprintln!("Could not find i3 config");
            return;
        }
    };

    // Apply theme to config
    let themed_config = apply_theme_to_config(&config_content, &theme);

    // Determine output location
    let output_file = if let Some(out_path) = output_path {
        out_path.clone()
    } else if save {
        config_file.clone()
    } else {
        return;
    };

    // Validate the config if i3 is available
    if !validate_config_path(&config_file) {
        exit(1);
    }

    // Write output
    if let Err(e) = fs::write(&output_file, &themed_config) {
        eprintln!("Failed to write output: {}", e);
        exit(1);
    }
}

fn apply_theme_to_config(config: &str, theme: &ColorScheme) -> String {
    let mut result = String::new();
    let mut in_bar_colors = false;
    let mut in_colors_block = false;

    for line in config.lines() {
        let trimmed = line.trim_start();

        // Track if we're in a bar block
        if trimmed.starts_with("bar") && trimmed.contains("{") {
            in_bar_colors = true;
            result.push_str(line);
            result.push('\n');
            continue;
        }

        if in_bar_colors && trimmed.starts_with("colors") && trimmed.contains("{") {
            in_colors_block = true;
            result.push_str(line);
            result.push('\n');
            continue;
        }

        if in_bar_colors && in_colors_block {
            if trimmed.starts_with("}") {
                in_colors_block = false;
                result.push_str(line);
                result.push('\n');
                continue;
            }

            // Check if the original line has trailing spaces
            let has_trailing_space = line.ends_with(' ');
            let trailing = if has_trailing_space { " " } else { "" };

            // Replace color lines
            if trimmed.starts_with("separator") {
                let indent = line.len() - trimmed.len();
                result.push_str(&" ".repeat(indent));
                result.push_str(&format!("separator {}{}\n", theme.bar_separator, trailing));
                continue;
            } else if trimmed.starts_with("background ") {
                let indent = line.len() - trimmed.len();
                result.push_str(&" ".repeat(indent));
                result.push_str(&format!("background {}{}\n", theme.bar_background, trailing));
                continue;
            } else if trimmed.starts_with("statusline ") {
                let indent = line.len() - trimmed.len();
                result.push_str(&" ".repeat(indent));
                result.push_str(&format!("statusline {}{}\n", theme.bar_statusline, trailing));
                continue;
            } else if trimmed.starts_with("focused_workspace") {
                let indent = line.len() - trimmed.len();
                result.push_str(&" ".repeat(indent));
                result.push_str(&format!("focused_workspace {} {} {}{}\n", 
                    theme.bar_focused_workspace.0, 
                    theme.bar_focused_workspace.1, 
                    theme.bar_focused_workspace.2,
                    trailing));
                continue;
            } else if trimmed.starts_with("active_workspace") {
                let indent = line.len() - trimmed.len();
                result.push_str(&" ".repeat(indent));
                result.push_str(&format!("active_workspace {} {} {}{}\n",
                    theme.bar_active_workspace.0,
                    theme.bar_active_workspace.1,
                    theme.bar_active_workspace.2,
                    trailing));
                continue;
            } else if trimmed.starts_with("inactive_workspace") {
                let indent = line.len() - trimmed.len();
                result.push_str(&" ".repeat(indent));
                result.push_str(&format!("inactive_workspace {} {} {}{}\n",
                    theme.bar_inactive_workspace.0,
                    theme.bar_inactive_workspace.1,
                    theme.bar_inactive_workspace.2,
                    trailing));
                continue;
            } else if trimmed.starts_with("urgent_workspace") {
                let indent = line.len() - trimmed.len();
                result.push_str(&" ".repeat(indent));
                result.push_str(&format!("urgent_workspace {} {} {}{}\n",
                    theme.bar_urgent_workspace.0,
                    theme.bar_urgent_workspace.1,
                    theme.bar_urgent_workspace.2,
                    trailing));
                continue;
            }
        }

        if in_bar_colors && trimmed.starts_with("}") && !in_colors_block {
            in_bar_colors = false;
        }

        // Handle client color lines
        if trimmed.starts_with("client.focused ") {
            result.push_str(&format!("client.focused {} {} {} {}\n",
                theme.client_focused.0,
                theme.client_focused.1,
                theme.client_focused.2,
                theme.client_focused.3));
            continue;
        } else if trimmed.starts_with("client.focused_inactive ") {
            result.push_str(&format!("client.focused_inactive {} {} {} {}\n",
                theme.client_focused_inactive.0,
                theme.client_focused_inactive.1,
                theme.client_focused_inactive.2,
                theme.client_focused_inactive.3));
            continue;
        } else if trimmed.starts_with("client.unfocused ") {
            result.push_str(&format!("client.unfocused {} {} {} {}\n",
                theme.client_unfocused.0,
                theme.client_unfocused.1,
                theme.client_unfocused.2,
                theme.client_unfocused.3));
            continue;
        } else if trimmed.starts_with("client.urgent ") {
            result.push_str(&format!("client.urgent {} {} {} {}\n",
                theme.client_urgent.0,
                theme.client_urgent.1,
                theme.client_urgent.2,
                theme.client_urgent.3));
            continue;
        }

        result.push_str(line);
        result.push('\n');
    }

    // Remove trailing newline if the original didn't have one
    if !config.ends_with('\n') && result.ends_with('\n') {
        result.pop();
    }

    result
}

fn validate_config_path(config_path: &PathBuf) -> bool {
    // Try to validate using i3's config checker
    let output = Command::new("i3")
        .arg("-C")
        .arg("-c")
        .arg(config_path)
        .output();

    match output {
        Ok(out) => out.status.success(),
        Err(e) => {
            eprintln!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}", 
                config_path.display(), e);
            false
        }
    }
}

fn convert_config_to_theme(_config_path: &PathBuf, _output_path: &Option<PathBuf>) {
    eprintln!("Converting config to theme not implemented");
}

