                let indent = line.len() - trimmed.len();
                result.push_str(&" ".repeat(indent));
                result.push_str(&format!("active_workspace {} {} {}{}\n",
                    theme.bar_active_workspace.0,
                    theme.bar_active_workspace.1,
                    theme.bar_active_workspace.2,
                    trailing));
                continue;
            } else if trimmed.starts_with("inactive_workspace") {
                let indent = line.len() - trimmed.len();
                result.push_str(&" ".repeat(indent));
                result.push_str(&format!("inactive_workspace {} {} {}{}\n",
                    theme.bar_inactive_workspace.0,
                    theme.bar_inactive_workspace.1,
                    theme.bar_inactive_workspace.2,
                    trailing));
                continue;
            } else if trimmed.starts_with("urgent_workspace") {
                let indent = line.len() - trimmed.len();
                result.push_str(&" ".repeat(indent));
                result.push_str(&format!("urgent_workspace {} {} {}{}\n",
                    theme.bar_urgent_workspace.0,
                    theme.bar_urgent_workspace.1,
                    theme.bar_urgent_workspace.2,
                    trailing));
                continue;
            }
        }

        if in_bar_colors && trimmed.starts_with("}") && !in_colors_block {
            in_bar_colors = false;
        }

        // Handle client color lines
        if trimmed.starts_with("client.focused ") {
            result.push_str(&format!("client.focused {} {} {} {}\n",
                theme.client_focused.0,
                theme.client_focused.1,
                theme.client_focused.2,
                theme.client_focused.3));
            continue;
        } else if trimmed.starts_with("client.focused_inactive ") {
            result.push_str(&format!("client.focused_inactive {} {} {} {}\n",
                theme.client_focused_inactive.0,
                theme.client_focused_inactive.1,
                theme.client_focused_inactive.2,
                theme.client_focused_inactive.3));
            continue;
        } else if trimmed.starts_with("client.unfocused ") {
            result.push_str(&format!("client.unfocused {} {} {} {}\n",
                theme.client_unfocused.0,
                theme.client_unfocused.1,
                theme.client_unfocused.2,
                theme.client_unfocused.3));
            continue;
        } else if trimmed.starts_with("client.urgent ") {
            result.push_str(&format!("client.urgent {} {} {} {}\n",
                theme.client_urgent.0,
                theme.client_urgent.1,
                theme.client_urgent.2,
                theme.client_urgent.3));
            continue;
        }

        result.push_str(line);
        result.push('\n');
    }

    // Remove trailing newline if the original didn't have one
    if !config.ends_with('\n') && result.ends_with('\n') {
        result.pop();
    }

    result
}

fn validate_config_path(config_path: &PathBuf) -> bool {
    // Try to validate using i3's config checker
    let output = Command::new("i3")
        .arg("-C")
        .arg("-c")
        .arg(config_path)
        .output();

    match output {
        Ok(out) => out.status.success(),
        Err(e) => {
            eprintln!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}", 
                config_path.display(), e);
            false
        }
    }
}

